import networkx as nx
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Construct a low union-cost source-rooted directed broadcast."""
    topology = BroadCastTopology(src, dsts, num_partitions)
    unique_dsts = list(dict.fromkeys(dsts))
    if not unique_dsts:
        return topology

    h = G.copy()
    if src in h:
        h.remove_edges_from(list(h.in_edges(src)))
    h.remove_edges_from(list(nx.selfloop_edges(h)))
    invalid = []
    for u, v, data in h.edges(data=True):
        try:
            if data.get("cost") is None or float(data["cost"]) < 0:
                invalid.append((u, v))
        except (TypeError, ValueError):
            invalid.append((u, v))
    h.remove_edges_from(invalid)

    try:
        src_lengths, src_paths = nx.single_source_dijkstra(h, src, weight="cost")
    except (nx.NetworkXNoPath, nx.NodeNotFound):
        return topology

    reachable = [d for d in unique_dsts if d in src_paths]
    if not reachable:
        return topology

    def path_edges(nodes):
        return tuple(zip(nodes, nodes[1:]))

    def union_cost(paths):
        used = set()
        for p in paths.values():
            used.update(p)
        return sum(float(h[u][v]["cost"]) for u, v in used)

    def routes_from_edges(edges):
        sub = nx.DiGraph()
        for u, v in edges:
            sub.add_edge(u, v, cost=h[u][v]["cost"])
        result = {}
        for d in reachable:
            try:
                nodes = nx.dijkstra_path(sub, src, d, weight="cost")
                result[d] = path_edges(nodes)
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                return None
        return result

    # Existing reliable direct-shortest-path seed.
    shortest_seed = {d: path_edges(src_paths[d]) for d in reachable}

    # New structural seed: grow a directed tree from every currently reachable
    # node, allowing relay chains deeper than a source-plus-two-relay star.
    dijkstra_cache = {src: (src_lengths, src_paths)}

    def from_node(node):
        if node not in dijkstra_cache:
            try:
                dijkstra_cache[node] = nx.single_source_dijkstra(
                    h, node, weight="cost"
                )
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                dijkstra_cache[node] = ({}, {})
        return dijkstra_cache[node]

    def growing_seed(order):
        active_nodes = {src}
        remaining = set(reachable)
        active_edges = set()
        while remaining:
            best = None
            frontier = sorted(active_nodes, key=str)
            targets = [d for d in order if d in remaining]
            for node in frontier:
                lengths, paths = from_node(node)
                for d in targets:
                    if d not in lengths:
                        continue
                    candidate = (
                        float(lengths[d]),
                        len(paths[d]),
                        str(node),
                        str(d),
                        node,
                        d,
                        paths[d],
                    )
                    if best is None or candidate[:4] < best[:4]:
                        best = candidate
            if best is None:
                break
            nodes = best[-1]
            active_edges.update(path_edges(nodes))
            active_nodes.update(nodes)
            remaining.remove(best[-2])

        if remaining:
            return None
        return routes_from_edges(active_edges)

    orders = [
        sorted(reachable, key=lambda d: (src_lengths[d], str(d))),
        sorted(reachable, key=lambda d: (-src_lengths[d], str(d))),
        list(reachable),
    ]
    seeds = [shortest_seed]
    for order in orders:
        candidate = growing_seed(order)
        if candidate is not None:
            seeds.append(candidate)

    # Add bounded relay-star seeds from frequently shared direct shortest paths.
    relay_frequency = {}
    for d in reachable:
        for node in src_paths[d]:
            if node != src:
                relay_frequency[node] = relay_frequency.get(node, 0) + 1
    relays = sorted(
        relay_frequency,
        key=lambda n: (-relay_frequency[n], src_lengths.get(n, float("inf")), str(n)),
    )[:12]

    for relay in relays:
        _, relay_paths = from_node(relay)
        candidate = {}
        feasible = True
        for d in reachable:
            if relay not in src_paths or d not in relay_paths:
                feasible = False
                break
            candidate[d] = path_edges(src_paths[relay] + relay_paths[d][1:])
        if feasible:
            seeds.append(candidate)

    def polish(initial, order):
        paths = {d: tuple(p) for d, p in initial.items()}
        counts = {}
        for p in paths.values():
            for e in p:
                counts[e] = counts.get(e, 0) + 1

        def marginal(u, v, data):
            return 0.0 if counts.get((u, v), 0) else float(data["cost"])

        for _ in range(4):
            changed = False
            for d in order:
                old = paths[d]
                for e in old:
                    counts[e] -= 1
                    if counts[e] == 0:
                        del counts[e]
                try:
                    nodes = nx.dijkstra_path(h, src, d, weight=marginal)
                    new = path_edges(nodes)
                except (nx.NetworkXNoPath, nx.NodeNotFound):
                    new = old
                paths[d] = new
                for e in new:
                    counts[e] = counts.get(e, 0) + 1
                changed = changed or new != old
            if not changed:
                break
        return paths

    best_paths = shortest_seed
    best_cost = union_cost(best_paths)
    for seed in seeds:
        for order in orders:
            candidate = polish(seed, order)
            cost = union_cost(candidate)
            if cost < best_cost:
                best_cost = cost
                best_paths = candidate

    for dst in unique_dsts:
        edge_pairs = best_paths.get(dst)
        if edge_pairs is None:
            continue
        edges = [[u, v, G[u][v]] for u, v in edge_pairs]
        for partition in range(topology.num_partitions):
            topology.set_dst_partition_paths(dst, partition, list(edges))
    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]


class BroadCastTopology:
    def __init__(
        self,
        src: str,
        dsts: List[str],
        num_partitions: int = 4,
        paths: Dict[str, SingleDstPath] = None,
    ):
        self.src = src
        self.dsts = dsts
        self.num_partitions = num_partitions
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {
                dst: {str(i): None for i in range(num_partitions)}
                for dst in dsts
            }

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        self.paths[dst][str(partition)] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)


def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    current_dir = os.path.dirname(os.path.abspath(__file__))
    cost = pd.read_csv(
        os.path.join(current_dir, "profiles/cost.csv")
        if cost_path is None else cost_path
    )
    throughput = pd.read_csv(
        os.path.join(current_dir, "profiles/throughput.csv")
        if throughput_path is None else throughput_path
    )

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] != row["dst_region"]:
            G.add_edge(
                row["src_region"],
                row["dst_region"],
                cost=None,
                throughput=num_vms * row["throughput_sent"] / 1e9,
            )

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    no_cost_pairs = [
        (u, v) for u, v, data in G.edges(data=True) if data.get("cost") is None
    ]
    print("Unable to get costs for: ", no_cost_pairs)
    return G


def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    return BroadCastTopology(src, dsts, num_partitions)


def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    return search_algorithm(src, dsts, G, num_partitions)

